def raises(exc, fn, label):
    try:
        fn()
    except exc:
        print("  PASS:", label)
        return True
    except Exception as e:  # noqa
        print("  FAIL:", label, "-> 得到", type(e).__name__)
        _FAILURES.append(label)
        return False
    print("  FAIL:", label, "-> 未抛异常")
    _FAILURES.append(label)
